//! ↩️ create-texture leaf-owned inverse reconstruction from exact base values.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfTexture;
use crate::artifacts::gltf::schema::mutations::create_texture::mutation::{validate, GltfCreateTexturePayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{textures_op, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.create-texture.v1.inverse";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfCreateTextureInverseOperation { Insert { position: usize, item: GltfTexture }, Delete { index: usize, removed: GltfTexture }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfCreateTextureInverse { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfCreateTexturePayload, pub operation: GltfCreateTextureInverseOperation }
async fn operation(payload: &GltfCreateTexturePayload, base: &GltfSnapshot) -> GltfCreateTextureInverseOperation { GltfCreateTextureInverseOperation::Delete { index: payload.position, removed: GltfTexture::default() } }
async fn touched_paths(payload: &GltfCreateTexturePayload) -> Vec<String> { vec![format!("document/textures/{}", payload.position)] }
pub async fn validate_inverse(inverse: &GltfCreateTextureInverse) -> Result<(), GltfTopLevelMutationRejection> { if inverse.id != ID || inverse.version != 1 { return Err(reject("gltf.mutation.invalid-inverse-envelope", "inverse", "descriptor identity does not match")); } if inverse.touched_paths != touched_paths(&inverse.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "inverse/touchedPaths", "paths must be concrete payload-derived locations")); } Ok(()) }
pub async fn apply_inverse(inverse: &GltfCreateTextureInverse, after: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_inverse(inverse)?; let operation = &inverse.operation; match operation { GltfCreateTextureInverseOperation::Insert { position, .. } if *position > after.document.textures.len() => return Err(reject("gltf.mutation.insert-out-of-range", "document/textures", "position must be within the collection")), GltfCreateTextureInverseOperation::Delete { index, .. } if *index >= after.document.textures.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/textures", "index must address an item")), GltfCreateTextureInverseOperation::Move { index, position } if *index >= after.document.textures.len() || *position >= after.document.textures.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/textures", "indices must address items")), GltfCreateTextureInverseOperation::Reorder { order } if order.is_empty() || order.len() != after.document.textures.len() || order.iter().collect::<std::collections::BTreeSet<_>>().len() != order.len() || order.iter().any(|index| *index >= after.document.textures.len()) => return Err(reject("gltf.mutation.invalid-permutation", "document/textures", "order must be a non-empty permutation")), _ => {} } let mut next = after.clone(); match operation { GltfCreateTextureInverseOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::Textures, &Change::Insert(*position))?; next.document.textures.insert(*position, item.clone());  }, GltfCreateTextureInverseOperation::Delete { index, .. } => { textures_op(&mut next, GltfTopLevelFamily::Textures, *index, None, None)?;  }, GltfCreateTextureInverseOperation::Move { index, position } => { textures_op(&mut next, GltfTopLevelFamily::Textures, *index, Some(*position), None)?;  }, GltfCreateTextureInverseOperation::Reorder { order } => { textures_op(&mut next, GltfTopLevelFamily::Textures, order[0], None, Some(order))?;  } } Ok(next) }
pub async fn encode(inverse: &GltfCreateTextureInverse) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(inverse).map_err(|error| reject("gltf.mutation.encode-failed", "inverse", error.to_string())) }
pub async fn derive(payload: &GltfCreateTexturePayload, base: &GltfSnapshot) -> Result<GltfCreateTextureInverse, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfCreateTextureInverse { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
